document.querySelectorAll('[data-filter]').forEach(button => {button.addEventListener('click', () => {const category = button.dataset.filter; let count = 0; document.querySelectorAll('[data-filter]').forEach(b => {const active = b === button; b.classList.toggle('active', active); b.setAttribute('aria-pressed', String(active));}); document.querySelectorAll('[data-category]').forEach(card => {card.hidden = category !== 'All' && card.dataset.category !== category; if (!card.hidden) count++;}); document.getElementById('filter-status').textContent = `Showing ${count} guides`;});});